import java.util.*;
import java.io.*;

public class Main {
    static char[][] grid1 = new char[15][15];
    static char[][] grid2 = new char[15][15];
    static int[][] directions = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
    static int[][][] index_map = new int[65][15][15];
    static int[][] capacity = new int[15][15];
    static int counter = 1;

    static class Edge {
        int u, v;
        long cap, flow;
        Edge() {}
        Edge(int u, int v, long cap) {
            this.u = u;
            this.v = v;
            this.cap = cap;
            this.flow = 0;
        }
    }

    static class MaxFlowSolver {
        int nodeCount;
        List<Edge> edges = new ArrayList<>();
        List<List<Integer>> graph;
        int[] dist, ptr;

        MaxFlowSolver(int N) {
            this.nodeCount = N;
            graph = new ArrayList<>();
            for (int i = 0; i < N; i++) {
                graph.add(new ArrayList<>());
            }
            dist = new int[N];
            ptr = new int[N];
        }

        void addEdge(int u, int v, long cap) {
            if (u != v) {
                edges.add(new Edge(u, v, cap));
                graph.get(u).add(edges.size() - 1);
                edges.add(new Edge(v, u, 0));
                graph.get(v).add(edges.size() - 1);
            }
        }

        boolean buildLevelGraph(int S, int T) {
            Arrays.fill(dist, nodeCount + 1);
            Queue<Integer> q = new LinkedList<>();
            q.offer(S);
            dist[S] = 0;
            while (!q.isEmpty()) {
                int u = q.poll();
                if (u == T) break;
                for (int k : graph.get(u)) {
                    Edge e = edges.get(k);
                    if (e.flow < e.cap && dist[e.v] > dist[e.u] + 1) {
                        dist[e.v] = dist[e.u] + 1;
                        q.offer(e.v);
                    }
                }
            }
            return dist[T] != nodeCount + 1;
        }

        long sendFlow(int u, int T, long flow) {
            if (u == T || flow == 0) return flow;
            for (int i = ptr[u]; i < graph.get(u).size(); i++) {
                int k = graph.get(u).get(i);
                Edge e = edges.get(k);
                Edge oe = edges.get(k ^ 1);
                if (dist[e.v] == dist[e.u] + 1) {
                    long amt = e.cap - e.flow;
                    if (flow != -1 && amt > flow) amt = flow;
                    long pushed = sendFlow(e.v, T, amt);
                    if (pushed > 0) {
                        e.flow += pushed;
                        oe.flow -= pushed;
                        return pushed;
                    }
                }
            }
            return 0;
        }

        long computeMaxFlow(int S, int T) {
            long totalFlow = 0;
            while (buildLevelGraph(S, T)) {
                Arrays.fill(ptr, 0);
                long flow;
                while ((flow = sendFlow(S, T, -1)) > 0) {
                    totalFlow += flow;
                }
            }
            return totalFlow;
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int t = Integer.parseInt(st.nextToken());

        for (int i = 1; i <= n; i++) {
            String line = br.readLine();
            for (int j = 1; j <= n; j++) {
                grid1[i][j] = line.charAt(j - 1);
            }
        }

        for (int i = 0; i <= t + 1; i++) {
            for (int j = 1; j <= n; j++) {
                String line = br.readLine();
                for (int k = 1; k <= n; k++) {
                    grid2[j][k] = line.charAt(k - 1);
                }
            }
        }

        for (int i = 1; i <= n; i++) {
            String line = br.readLine();
            for (int j = 1; j <= n; j++) {
                index_map[0][i][j] = counter++;
            }
        }
        counter++;
        for (int i = 1; i <= n; i++) {
            String line = br.readLine();
            for (int j = 1; j <= n; j++) {
                grid2[i][j] = line.charAt(j - 1);
            }
        }

        for (int i = 1; i <= n; i++) {
            Arrays.fill(capacity[i], -1);
        }

        Queue<int[]> q = new LinkedList<>();
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                if (grid1[i][j] == 'Z') {
                    q.offer(new int[]{i, j});
                    capacity[i][j] = 0;
                }
            }
        }

        while (!q.isEmpty()) {
            int[] pos = q.poll();
            int y = pos[0], x = pos[1];
            for (int[] dir : directions) {
                int ny = y + dir[0], nx = x + dir[1];
                if (ny >= 1 && ny <= n && nx >= 1 && nx <= n && grid1[ny][nx] != 'Y' && capacity[ny][nx] == -1) {
                    capacity[ny][nx] = capacity[y][x] + 1;
                    q.offer(new int[]{ny, nx});
                }
            }
        }

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                if (capacity[i][j] == -1 || capacity[i][j] > t) {
                    capacity[i][j] = (int) 1e9;
                }
            }
        }

        int source = 0;
        int sink = counter - 1;
        MaxFlowSolver mf = new MaxFlowSolver(counter);

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                if (grid1[i][j] >= '1' && grid1[i][j] <= '9') {
                    int capVal = grid1[i][j] - '0';
                    mf.addEdge(source, index_map[0][i][j], capVal);
                }
            }
        }

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                if (grid1[i][j] == 'Y' || grid1[i][j] == 'Z') continue;
                for (int[] dir : directions) {
                    int ny = i + dir[0], nx = j + dir[1];
                    if (ny >= 1 && ny <= n && nx >= 1 && nx <= n && grid1[ny][nx] != 'Y' && grid1[ny][nx] != 'Z') {
                        for (int x = 0; x < t; x++) {
                            if (capacity[ny][nx] >= x + 1 && capacity[i][j] > x) {
                                mf.addEdge(index_map[x][i][j], index_map[x + 1][ny][nx], 1000);
                            }
                        }
                    }
                }
            }
        }

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                if (grid1[i][j] == 'Y' || grid1[i][j] == 'Z') continue;
                for (int x = 0; x <= t; x++) {
                    if (grid2[i][j] >= '1' && grid2[i][j] <= '9') {
                        int capVal = grid2[i][j] - '0';
                        mf.addEdge(index_map[x][i][j], index_map[t + 1][i][j], capVal);
                    }
                }
            }
        }

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                if (grid1[i][j] == 'Y' || grid1[i][j] == 'Z') continue;
                if (grid2[i][j] >= '1' && grid2[i][j] <= '9') {
                    int capVal = grid2[i][j] - '0';
                    mf.addEdge(index_map[t + 1][i][j], sink, capVal);
                }
            }
        }

        System.out.println(mf.computeMaxFlow(source, sink));
    }
}
